import contentJson from "@/content/content.json";
import type { Content } from "@/engine/types";

/**
 * Juliana's content, as a module.
 *
 * `content/content.json` is generated by `scripts/import-content` and
 * **committed**, so it is a build input, not a runtime resource: importing it
 * lets the bundler inline it into the page's own JS. That is what makes the
 * calculator work with no network after first load — there is no fetch to fail.
 *
 * **How this satisfies "cached on first load and refreshed in the background
 * when `version` changes"** (`docs/03-content-schema.md`, `docs/01` § Offline):
 * the content ships *inside* the JS bundle, so the service worker
 * (`@crivelo/pwa`, landing in RMP-259) is what caches and refreshes it. A new
 * import changes the bundle hash, the worker fetches the new asset in the
 * background and activates it on the next launch — exactly the described
 * behaviour, one layer down. There is no separate content fetch to version, so
 * `content.version` is a display and diagnostic field (it tells a student which
 * sheet revision they are holding when they message Juliana), not a runtime
 * refresh trigger. A hand-rolled fetch + cache layer would duplicate the
 * service worker and add a failure mode the static import does not have.
 *
 * The cast is the seam where the JSON becomes typed. The importer is the single
 * place chemistry and validation enter the system (every enum, reference and
 * formula is checked there, and no JSON is written when anything fails), so the
 * app trusts the file rather than re-validating it. TypeScript widens the JSON's
 * literals to `string`/`number`, hence `unknown` in the middle.
 */
export const content = contentJson as unknown as Content;
